INSERT INTO substitutes VALUES ('nacl-1000', 'lr-1000', 'Balanced crystalloid; avoid where hyperkalemia is a concern');
INSERT INTO substitutes VALUES ('lr-1000', 'nacl-1000', 'Normal saline; monitor for hyperchloremic acidosis');
